/* Search real destinations and resume the exact saved lesson step. */
(()=>{
 const dialog=document.querySelector('#space-navigator'),grid=dialog.querySelector('.space-grid');
 const pages=[['#research','Research studio','Projects papers library map evidence'],['#home','Home','Discovery atlas'],['#academy','Academy','All research lessons'],['#journey','Research journey','Milestones and progress'],['#toolkit','Toolkit','Downloadable research resources'],['#notebook','Idea notebook','Notes and observations'],['#notebook/draft','Proposal studio','Assembled lesson drafts'],['#notebook/readiness','Readiness review','Proposal checklist'],['#seminars','Workshops','Self-guided sessions']];
 const index=[...pages.map(([href,title,description])=>({href,title,description,kind:'Space'})),...course.map((c,i)=>({href:'#lesson/'+i,title:c.title,description:c.subtitle+' '+stages[i][0],kind:'Lesson '+(i+1)})),...resources.map(r=>({href:'#resource/'+r.id,title:r.name,description:r.desc+' '+r.category,kind:'Resource'})),...phases.map((p,i)=>({href:'#workshop/'+i,title:p.name,description:p.desc,kind:'Workshop'}))];
 const search=document.createElement('div');search.className='hub-search';search.innerHTML='<label for="hub-query">Find a lesson, resource, project, source, evidence, or note</label><div>'+icon('search')+'<input id="hub-query" type="search" placeholder="Try literature, proposal, or methods" autocomplete="off" aria-controls="hub-results"><button type="button" aria-label="Clear search" hidden>'+icon('close')+'</button></div><p id="hub-result-status" role="status" aria-live="polite"></p>';grid.before(search);
 dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();dialog.close()}});
 const results=document.createElement('div');results.id='hub-results';results.className='hub-results';results.hidden=true;grid.after(results);const input=search.querySelector('input'),clear=search.querySelector('button'),status=search.querySelector('[role=status]');
 async function filter(){const query=input.value.trim().toLowerCase();dialog.classList.toggle('is-searching',!!query);clear.hidden=!query;grid.hidden=!!query;results.hidden=!query;if(!query){results.innerHTML='';status.textContent='';return}const words=query.split(/\s+/),all=[...index,...await localIndex()],found=all.filter(x=>words.every(w=>(x.title+' '+x.description+' '+x.kind).toLowerCase().includes(w))).slice(0,60);status.textContent=found.length+' '+(found.length===1?'result':'results');results.innerHTML=found.length?found.map(x=>'<a href="'+x.href+'"><span class="result-kind">'+esc(x.kind)+'</span><div><h3>'+esc(x.title)+'</h3><p>'+esc(x.description)+'</p></div>'+icon('arrow')+'</a>').join(''):'<div class="hub-empty"><h3>No matches yet</h3><p>Try a broader term, such as “question”, “evidence”, or “draft”.</p></div>'}
 input.addEventListener('input',filter);clear.onclick=()=>{input.value='';filter();input.focus()};search.addEventListener('keydown',e=>{if(e.key==='Enter'&&input===document.activeElement){const first=results.querySelector('a');if(first){e.preventDefault();first.click()}}if(e.key==='ArrowDown'&&input===document.activeElement){const first=(results.hidden?grid:results).querySelector('a');if(first){e.preventDefault();first.focus()}}});results.addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp'].includes(e.key))return;const links=[...results.querySelectorAll('a')],i=links.indexOf(document.activeElement);if(i<0)return;e.preventDefault();if(e.key==='ArrowUp'&&i===0)input.focus();else links[Math.max(0,Math.min(links.length-1,i+(e.key==='ArrowDown'?1:-1)))].focus()});
 new MutationObserver(()=>{if(dialog.open){input.value='';filter();input.focus()}}).observe(dialog,{attributes:true,attributeFilter:['open']});
 async function localIndex(){const out=[];try{const req=indexedDB.open('rei-research',1);const db=await new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onupgradeneeded=()=>{req.transaction.abort()}});if(db.objectStoreNames.contains('projects')){const tx=db.transaction('projects','readonly'),rows=await new Promise((resolve,reject)=>{const r=tx.objectStore('projects').getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)});for(const p of rows){const base='#research/'+encodeURIComponent(p.id)+'/';const add=(href,kind,title,body)=>{const text=[title,body].filter(Boolean).join(' ');if(text.trim())out.push({href,kind,title,description:text.slice(0,180)})};add(base+'library','Project',p.title,p.question);add(base+'proposal','Proposal',p.title,p.proposal);for(const x of p.papers||[])add(base+'library','Paper',x.title,[x.authors,x.abstract,x.notes,x.doi].join(' '));for(const [i,x] of (p.evidence||[]).entries())add(base+'evidence','Evidence note '+(i+1),x.findings,[x.quote,x.purpose,x.method,x.context,x.limitations,x.relevance,x.studyType,x.sample,x.transferability,x.conflicts].join(' '));for(const [i,x] of (p.workbench?.claims||[]).entries())add(base+'claims','Claim '+(i+1),x.text,x.status);for(const x of p.workbench?.decisions||[])add(base+'review','Decision',x.text,x.date);for(const x of p.workbench?.searches||[])add(base+'review','Search log',x.query,[x.database,x.notes].join(' '))}db.close()}}catch{}try{const saved=JSON.parse(localStorage.getItem('rrh-v2')||'{}');for(const n of saved.notes||[])out.push({href:'#notebook',kind:'Notebook note',title:n.title,description:(n.body||'').slice(0,180)});for(const [i,d] of Object.entries(saved.drafts||{}))if(typeof d==='string'&&d.trim())out.push({href:'#lesson/'+i+'/write',kind:'Lesson draft',title:course[+i]?.title||'Lesson draft',description:d.slice(0,180)})}catch{}return out}
 const stepNames={learn:'Learn the concept',example:'Study an example',write:'Write your draft',check:'Check understanding'};
 function setup(){const page=document.body.dataset.page;
 if(page==='academy'&&state.resume){const r=state.resume,c=course[r.lesson],done=state.completed.includes(r.lesson),href='#lesson/'+r.lesson+(r.step==='learn'?'':'/'+r.step);const banner=document.createElement('div');banner.className='resume-panel';banner.innerHTML='<div class="resume-orbit" aria-hidden="true">'+icon(done?'check':'play')+'</div><div><span class="eyebrow">'+(done?'LAST VISITED MILESTONE':'CONTINUE WHERE YOU LEFT OFF')+'</span><h2>'+esc(c.title)+'</h2><p>Lesson '+(r.lesson+1)+' · '+stepNames[r.step]+'</p></div><a class="button primary" href="'+href+'">'+(done?'Revisit lesson':'Resume lesson')+' '+icon('arrow')+'</a>';document.querySelector('.toolbar').before(banner)}
 const flow=document.querySelector('.lesson-flow');if(flow){const i=Number(location.hash.split('/')[1]);const write=flow.querySelector('a[href$="/write"] strong'),check=flow.querySelector('a[href$="/check"] strong');if(write)write.insertAdjacentHTML('beforeend','<small>'+wordCount(state.drafts[i]||'')+' words saved</small>');if(check)check.insertAdjacentHTML('beforeend','<small>'+(state.quiz[i]===course[i].correct?'Answer checked':'Knowledge check')+'</small>')}
 }
 addEventListener('rrh:route',setup);setup();
 document.addEventListener('input',e=>{if(e.target.id!=='exercise-text')return;const badge=document.querySelector('.lesson-flow a[href$="/write"] small');if(badge)badge.textContent=wordCount(e.target.value)+(storageAvailable?' words saved':' words · not saved')});
})();


